# Terraform Module: S3 + RDS + IAM

I'll provide a complete, production-ready module structure supporting dev/prod environments via workspaces and `.tfvars` files.

## Directory Structure

```
.
├── modules/
│   └── infrastructure/
│       ├── main.tf
│       ├── variables.tf
│       ├── outputs.tf
│       ├── s3.tf
│       ├── rds.tf
│       └── iam.tf
├── environments/
│   ├── dev.tfvars
│   └── prod.tfvars
├── terraform.tf
├── main.tf
├── variables.tf
└── outputs.tf
```

---

## Root Module: `terraform.tf`

```hcl
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  # Uncomment for remote state; configure bucket/key per environment
  # backend "s3" {
  #   bucket         = "my-terraform-state"
  #   key            = "infrastructure/terraform.tfstate"
  #   region         = "us-east-1"
  #   encrypt        = true
  #   dynamodb_table = "terraform-lock"
  # }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Environment = var.environment
      Project     = var.project_name
      ManagedBy   = "Terraform"
      CreatedAt   = timestamp()
    }
  }
}
```

---

## Root Module: `variables.tf`

```hcl
variable "aws_region" {
  description = "AWS region for resources"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name (dev or prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be 'dev' or 'prod'."
  }
}

variable "project_name" {
  description = "Project name for resource naming"
  type        = string
}

variable "bucket_name" {
  description = "Name of the S3 bucket"
  type        = string
}

variable "rds_instance_class" {
  description = "RDS instance class"
  type        = string
}

variable "rds_allocated_storage" {
  description = "Allocated storage for RDS in GB"
  type        = number
}

variable "rds_multi_az" {
  description = "Enable Multi-AZ for RDS"
  type        = bool
}

variable "rds_backup_retention_days" {
  description = "Backup retention period in days"
  type        = number
}

variable "db_password" {
  description = "RDS master password (use AWS Secrets Manager or Terraform Cloud sensitive variables)"
  type        = string
  sensitive   = true
}

variable "enable_cross_region_replication" {
  description = "Enable S3 cross-region replication (prod only)"
  type        = bool
  default     = false
}

variable "replica_region" {
  description = "Region for S3 cross-region replication"
  type        = string
  default     = "us-west-2"
}

variable "iam_role_name" {
  description = "IAM role name for service accounts"
  type        = string
}

variable "allowed_s3_actions" {
  description = "List of S3 actions allowed by service role"
  type        = list(string)
  default     = ["s3:GetObject", "s3:PutObject"]
}
```

---

## Root Module: `main.tf`

```hcl
module "infrastructure" {
  source = "./modules/infrastructure"

  environment                    = var.environment
  project_name                   = var.project_name
  bucket_name                    = var.bucket_name
  rds_instance_class             = var.rds_instance_class
  rds_allocated_storage          = var.rds_allocated_storage
  rds_multi_az                   = var.rds_multi_az
  rds_backup_retention_days      = var.rds_backup_retention_days
  db_password                    = var.db_password
  enable_cross_region_replication = var.enable_cross_region_replication
  replica_region                 = var.replica_region
  iam_role_name                  = var.iam_role_name
  allowed_s3_actions             = var.allowed_s3_actions
}
```

