## Module: `modules/infrastructure/rds.tf`

```hcl
# Security group for RDS
resource "aws_security_group" "rds_sg" {
  name        = "${var.project_name}-rds-sg"
  description = "Security group for RDS PostgreSQL"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"] # Restrict to VPC CIDR; adjust as needed
    description = "PostgreSQL from VPC"
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.project_name}-rds-sg"
  }
}

# DB subnet group (assumes default VPC; adapt for custom VPC)
resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "${var.project_name}-db-subnet-group"
  subnet_ids = data.aws_subnets.default.ids

  tags = {
    Name = "${var.project_name}-db-subnet-group"
  }
}

data "aws_subnets" "default" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
}

data "aws_vpc" "default" {
  default = true
}

# RDS PostgreSQL instance
resource "aws_db_instance" "postgres" {
  identifier              = "${var.project_name}-postgres-${var.environment}"
  engine                  = "postgres"
  engine_version          = "15.4" # Adjust to desired version
  instance_class          = var.rds_instance_class
  allocated_storage       = var.rds_allocated_storage
  storage_type            = "gp3"
  storage_encrypted       = true
  username                = "dbadmin"
  password                = var.db_password
  db_name                 = "appdb"
  port                    = 5432
  publicly_accessible     = false
  skip_final_snapshot     = var.environment == "dev" ? true : false
  final_snapshot_identifier = var.environment == "prod" ? "${var.project_name}-postgres-final-snapshot-${formatdate("YYYY-MM-DD-hhmm", timestamp())}" : null
  backup_retention_period = var.rds_backup_retention_days
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:00-sun:05:00"
  multi_az                = var.rds_multi_az
  deletion_protection     = var.environment == "prod" ? true : false
  db_subnet_group_name    = aws_db_subnet_group.rds_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.rds_sg.id]
  enable_cloudwatch_logs_exports = [
    "postgresql"
  ]
  copy_tags_to_snapshot = true
  performance_insights_enabled = var.environment == "prod" ? true : false
  performance_insights_retention_period = var.environment == "prod" ? 7 : null

  tags = {
    Name = "${var.project_name}-postgres-${var.environment}"
  }
}

# Store RDS connection string in AWS Secrets Manager
resource "aws_secretsmanager_secret" "rds_connection_string" {
  name                    = "${var.project_name}/rds/connection-string"
  description             = "RDS connection string for ${var.environment}"
  recovery_window_in_days = var.environment == "prod" ? 30 : 7

  tags = {
    Name = "${var.project_name}-rds-secret"
  }
}

resource "aws_secretsmanager_secret_version" "rds_connection_string" {
  secret_id = aws_secretsmanager_secret.rds_connection_string.id
  secret_string = jsonencode({
    host     = aws_db_instance.postgres.endpoint
    port     = aws_db_instance.postgres.port
    username = aws_db_instance.postgres.username
    password = var.db_password
    dbname   = aws_db_instance.postgres.db_name
    engine   = "postgresql"
    url      = "postgresql://${aws_db_instance.postgres.username}:${var.db_password}@${aws_db_instance.postgres.endpoint}:5432/${aws_db_instance.postgres.db_name}"
  })
}
```

