## Module: `modules/infrastructure/iam.tf`

```hcl
# IAM role for service accounts
resource "aws_iam_role" "service_account_role" {
  name               = var.iam_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = var.iam_role_name
  }
}

# S3 bucket access policy
resource "aws_iam_policy" "s3_access_policy" {
  name        = "${var.project_name}-s3-access"
  description = "S3 access for ${var.environment}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3BucketAccess"
        Effect = "Allow"
        Action = var.allowed_s3_actions
        Resource = [
          aws_s3_bucket.app_bucket.arn,
          "${aws_s3_bucket.app_bucket.arn}/*"
        ]
      },
      # Restrict to non-wildcard actions on prod
      var.environment == "prod" ? {
        Sid    = "DenyWildcardActions"
        Effect = "Deny"
        Action = [
          "s3:*"
        ]
        Resource = "*"
        Condition = {
          StringLike = {
            "aws:PrincipalArn" = aws_iam_role.service_account_role.arn
          }
        }
      } : null
    ]
  })
}

# RDS connection access policy
resource "aws_iam_policy" "rds_access_policy" {
  name        = "${var.project_name}-rds-access"
  description = "RDS access for ${var.environment}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "RDSConnect"
        Effect = "Allow"
        Action = [
          "rds-db:connect"
        ]
        Resource = "arn:aws:rds:*:${data.aws_caller_identity.current.account_id}:db:${aws_db_instance.postgres.identifier}"
      }
    ]
  })
}

# Secrets Manager access policy
resource "aws_iam_policy" "secrets_access_policy" {
  name        = "${var.project_name}-secrets-access"
  description = "Secrets Manager access for RDS connection string"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadRDSSecret"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = aws_secretsmanager_secret.rds_connection_string.arn
      }
    ]
  })
}

# Attach policies to role
resource "aws_iam_role_policy_attachment" "s3_access" {
  role       = aws_iam_role.service_account_role.name
  policy_arn = aws_iam_policy.s3_access_policy.arn
}

resource "aws_iam_role_policy_attachment" "rds_access" {
  role       = aws_iam_role.service_account_role.name
  policy_arn = aws_iam_policy.rds_access_policy.arn
}

resource "aws_iam_role_policy_attachment" "secrets_access" {
  role       = aws_iam_role.service_account_role.name
  policy_arn = aws_iam_policy.secrets_access_policy.arn
}

# Data source for current AWS account
data "aws_caller_identity" "current" {}
```

